<div class="card mt-4" style="max-width: 500px;">
    <div class="card-body">
        <h5 class="card-title">Theme</h5>
        <div class="btn-group mb-4" role="group">
            @foreach (var mode in Enum.GetValues<ThemeMode>())
            {
                var isActive = ThemeService.Theme == mode;
                <button type="button"
                        class="btn @(isActive ? "btn-primary" : "btn-outline-primary")"
                        @onclick="() => ThemeService.SetTheme(mode)">
                    @(mode switch
                    {
                        ThemeMode.Light  => "☀️ Light",
                        ThemeMode.Dark   => "🌙 Dark",
                        _                => "💻 System"
                    })
                </button>
            }
        </div>

        <h5 class="card-title">Accent Color</h5>
        <div class="d-flex align-items-center gap-3">
            <input type="color"
                   class="form-control form-control-color"
                   value="@ThemeService.AccentColor"
                   @onchange="OnAccentColorChanged" />
            <span class="text-muted">@ThemeService.AccentColor</span>
        </div>

        <div class="mt-4 p-3 rounded"
             style="background-color: var(--app-accent-color, #0d6efd); color: white;">
            Preview: This box uses your accent color.
        </div>
    </div>
</div>

@code {
    protected override void OnInitialized()
    {
        ThemeService.OnChange += OnThemeChanged;
    }

    private void OnAccentColorChanged(ChangeEventArgs e)
    {
        if (e.Value is string color && !string.IsNullOrWhiteSpace(color))
        {
            ThemeService.SetAccentColor(color);
        }
    }

    private void OnThemeChanged()
    {
        InvokeAsync(StateHasChanged);
    }

    public void Dispose()
    {
        ThemeService.OnChange -= OnThemeChanged;
    }
}

namespace sv_072deebe1e7245488ff8601104ae564d.Services;

public enum ThemeMode
{
    Light,
    Dark,
    System
}

/// <summary>
/// Scoped service that holds theme state for a single circuit.
/// All interactive components on the same page share this instance.
/// </summary>
public class ThemeService
{
    public ThemeMode Theme { get; private set; } = ThemeMode.System;
    public string AccentColor { get; private set; } = "#0d6efd";

    public event Action? OnChange;

    public void SetTheme(ThemeMode theme)
    {
        if (Theme == theme) return;
        Theme = theme;
        OnChange?.Invoke();
    }

    public void SetAccentColor(string color)
    {
        if (AccentColor == color) return;
        AccentColor = color;
        OnChange?.Invoke();
    }

    /// <summary>
    /// Initializes state without firing OnChange (used during hydration from cookies).
    /// </summary>
    public void Initialize(ThemeMode theme, string accentColor)
    {
        Theme = theme;
        AccentColor = accentColor;
    }
}

// Resolves "system" to the actual preference, or returns light/dark as-is.
function resolveTheme(theme) {
    if (theme === 'system') {
        return window.matchMedia('(prefers-color-scheme: dark)').matches ? 'dark' : 'light';
    }
    return theme;
}

export function applyTheme(theme, accentColor) {
    const resolved = resolveTheme(theme);
    document.documentElement.setAttribute('data-bs-theme', resolved);
    document.documentElement.style.setProperty('--app-accent-color', accentColor);

    setCookie('app-theme', theme);
    setCookie('app-accent', encodeURIComponent(accentColor));
}

export function getStoredTheme() {
    const theme = getCookie('app-theme') || 'system';
    const accent = decodeURIComponent(getCookie('app-accent') || '%230d6efd');
    return { theme, accentColor: accent };
}

// Re-resolve when OS preference changes (only relevant when theme === "system").
export function watchSystemPreference(dotNetRef) {
    const mq = window.matchMedia('(prefers-color-scheme: dark)');
    mq.addEventListener('change', () => {
        dotNetRef.invokeMethodAsync('OnSystemPreferenceChanged');
    });
}

function setCookie(name, value) {
    document.cookie = `${name}=${value};path=/;max-age=31536000;SameSite=Lax`;
}

function getCookie(name) {
    const match = document.cookie.match(new RegExp('(?:^|; )' + name + '=([^;]*)'));
    return match ? match[1] : null;
}

@rendermode InteractiveServer
@inject ThemeService ThemeService
@inject IJSRuntime JS
@implements IDisposable

<span class="badge rounded-pill me-3"
      style="background-color: @ThemeService.AccentColor; color: white; font-size: 0.8rem;">
    @ThemeIcon @ThemeService.Theme
</span>

@code {
    private IJSObjectReference? _module;
    private DotNetObjectReference<ThemeIndicator>? _dotNetRef;

    private string ThemeIcon => ThemeService.Theme switch
    {
        ThemeMode.Light  => "☀️",
        ThemeMode.Dark   => "🌙",
        _                => "💻"
    };

    protected override async Task OnAfterRenderAsync(bool firstRender)
    {
        if (!firstRender) return;

        _module = await JS.InvokeAsync<IJSObjectReference>("import", "./js/theme-interop.js");

        // Hydrate service from cookies on first load
        var stored = await _module.InvokeAsync<StoredTheme>("getStoredTheme");
        if (Enum.TryParse<ThemeMode>(stored.Theme, ignoreCase: true, out var mode))
        {
            ThemeService.Initialize(mode, stored.AccentColor);
        }

        await ApplyThemeAsync();

        // Watch for OS dark/light preference changes
        _dotNetRef = DotNetObjectReference.Create(this);
        await _module.InvokeVoidAsync("watchSystemPreference", _dotNetRef);

        ThemeService.OnChange += OnThemeChanged;
        StateHasChanged();
    }

    [JSInvokable]
    public async Task OnSystemPreferenceChanged()
    {
        if (ThemeService.Theme == ThemeMode.System)
        {
            await ApplyThemeAsync();
        }
    }

    private async void OnThemeChanged()
    {
        await InvokeAsync(async () =>
        {
            await ApplyThemeAsync();
            StateHasChanged();
        });
    }

    private async Task ApplyThemeAsync()
    {
        if (_module is not null)
        {
            await _module.InvokeVoidAsync("applyTheme",
                ThemeService.Theme.ToString().ToLowerInvariant(),
                ThemeService.AccentColor);
        }
    }

    public void Dispose()
    {
        ThemeService.OnChange -= OnThemeChanged;
        _dotNetRef?.Dispose();
    }

    private sealed record StoredTheme(string Theme, string AccentColor);
}

